

local System = _G.System


local function getMetatable(prefix)
    return {
        __prefix= prefix,
        __index = function(mytable, key)
            return function(...)
                if mytable.isnil then
                    return System[prefix][key](nil,select(2,...))
                else
                    return System[prefix][key](mytable.item,select(2,...))
                end
            end
          end
    }
end

local function wrap(prefix)
  return  function(x)
        local t={
            item=x,
            isnil = x==nil
        }
        local metatable = getMetatable(prefix)
        setmetatable(t,metatable)
        return t
    end
end

-- wraps
System.S = wrap("String")
System.N = wrap("Number")
System.C = wrap("Char")
System.B = wrap("Boolean")
System.D = wrap("DateTime")
System.De = wrap("Delegate")
System.E = wrap("Enum")

return {i=1}